('Each call sign is a row: pick the member for it.', 'zu', 'Yilelo nalelo phawu lokubiza liwumugqa: khetha ilungu lalo.'),
('Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.', 'zu', 'Yilelo nalelo phawu lokubiza liyisikhala esisodwa somsebenzi: lapho ligada khona, ama-awa alo, ikhefu lalo nesikhundla elisidingayo. Ukwabela Umsebenzi kubhuka abasebenzi kulezi.'),
