('Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.', 'zu', 'Ukuvula isici akunikezi indima lutho i-matrix yemizila nokuphepha kwezinga lomugqa obekungeke kukuvumele — lezi zinhlelo zombili zisebenza ndawonye. Ukuvala esisodwa kusifihla yonke indawo futhi kwenza imizila yaso yeseva yenqabe, kulo mqashi kuphela.'),
