('Everything is filled in.', 'zu', 'Konke kugcwalisiwe.'),
('Everything on the register for one ID number or one vehicle: fines, payments and when they were made, and what is owed today.', 'zu', 'Konke okusekurejista kwenombolo kamazisi eyodwa noma imoto eyodwa: izinhlawulo, izinkokhelo nokuthi zenziwa nini, nokukweletwayo namuhla.'),
('Everything that came in while you were busy, with what still needs your acknowledgement.', 'zu', 'Konke okufike ngesikhathi umatasa, nalokho okusadinga ukuthi ukwamukele.'),
