('Official insignia belong to the municipality and its services, so the platform ships none — upload each department''s real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department''s colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.', 'zu', 'Izimpawu ezisemthethweni ezikamasipala nezinsizakalo zawo, ngakho uhlelo aluzifaki — layisha uphawu lwangempela lomnyango ngamunye lapha futhi luvela yonke indawo ngokushesha. Kuze kube yilapho, ibheji lezinhlamvu zokuqala liboniswa ngemibala yalowo mnyango, ngakho akukho okubukeka kungaqediwe. I-PNG noma i-SVG enendawo engemuva ecwebile isebenza kangcono; izithombe eziyisikwele zifundeka kahle uma zincane.'),
