('Secrets live in server environment variables and are never stored in the database or sent to the browser — this page only reports whether each one is present. The switch and the JSON parameters below are stored in the database and take effect immediately, with no redeploy. Adding or changing a secret requires setting it on the host and redeploying.', 'zu', 'Izimfihlo zigcinwa ezintweni eziguquguqukayo zemvelo yeseva futhi azikaze zigcinwe kusizindalwazi noma zithunyelwe esipheqululini — leli khasi libika kuphela ukuthi ngayinye ikhona yini. Iswishi namapharamitha e-JSON angezansi agcinwa kusizindalwazi futhi asebenza ngokushesha, ngaphandle kokufaka kabusha. Ukwengeza noma ukushintsha imfihlo kudinga ukuyisetha kumsingathi bese ufaka kabusha.'),
